INSERT INTO public.tours (title, category, duration, price_label, price_ksh, image_url, short_description, description, highlights, itinerary, included, excluded, sort_order) VALUES
('Masai Mara Wildlife Safari', 'wildlife', '4 Days / 3 Nights', 'From KSh 162,500', 162500, 'masai-mara', 'Experience the world-famous Masai Mara with its abundant wildlife and the Great Migration.', 'Embark on an unforgettable journey to the Masai Mara National Reserve, one of Africa''s most magnificent game reserves. Witness the Big Five, experience the Great Migration, and immerse yourself in the breathtaking landscapes of the Kenyan savanna.', '["Big Five game viewing","Great Migration (seasonal)","Maasai village visit","Sunset game drives","Luxury tented camp accommodation"]'::jsonb, '[{"day":"Day 1","title":"Nairobi to Masai Mara","description":"Depart Nairobi early morning, scenic drive through the Great Rift Valley. Afternoon game drive."},{"day":"Day 2","title":"Full Day Game Drive","description":"Full day exploring the reserve with morning and afternoon game drives."},{"day":"Day 3","title":"Mara Exploration","description":"Optional hot air balloon safari. Visit a Maasai village. Evening game drive."},{"day":"Day 4","title":"Return to Nairobi","description":"Morning game drive en route. Arrive Nairobi by evening."}]'::jsonb, '["Transport in 4x4 safari vehicle","Professional safari guide","Full board accommodation","Park entry fees","Game drives as per itinerary","Bottled water"]'::jsonb, '["International flights","Visa fees","Travel insurance","Tips and gratuities","Hot air balloon safari","Personal expenses"]'::jsonb, 1),
('Diani Beach Tropical Escape', 'beach', '5 Days / 4 Nights', 'From KSh 127,400', 127400, 'beach-holiday', 'Relax on the pristine white sands of Diani Beach, Kenya''s premier coastal paradise.', 'Unwind at Diani Beach, consistently rated among Africa''s best beaches. Crystal-clear turquoise waters, swaying palm trees, and world-class resorts await. Perfect for a romantic getaway or family vacation.', '["White sand beaches","Snorkeling & diving","Dolphin watching","Wasini Island day trip","Kisite Marine Park"]'::jsonb, '[{"day":"Day 1","title":"Arrival at Diani","description":"Transfer from Mombasa airport to your beach resort. Evening at leisure."},{"day":"Day 2","title":"Beach & Water Sports","description":"Full day of beach activities, snorkeling, or diving excursions."},{"day":"Day 3","title":"Wasini Island Excursion","description":"Full day trip to Wasini Island and Kisite Marine Park for dolphin watching."},{"day":"Day 4","title":"Cultural & Leisure","description":"Visit Shimba Hills or enjoy spa treatments at the resort."},{"day":"Day 5","title":"Departure","description":"Morning at leisure. Transfer to airport."}]'::jsonb, '["Airport transfers","Beach resort accommodation","Breakfast daily","Wasini Island tour","Snorkeling equipment"]'::jsonb, '["Flights","Lunch and dinner","Travel insurance","Personal expenses","Optional activities"]'::jsonb, 2),
('Kenya Cultural Heritage Tour', 'cultural', '6 Days / 5 Nights', 'From KSh 188,500', 188500, 'cultural-tour', 'Discover the rich cultural heritage of Kenya''s diverse communities and traditions.', 'Journey through Kenya''s cultural heartland, meeting the Maasai, Samburu, and other communities. Experience traditional dances, visit local markets, and gain deep insight into Kenya''s living heritage.', '["Maasai Mara cultural immersion","Traditional homestead visits","Local market tours","Traditional cuisine experiences","Artisan craft workshops"]'::jsonb, '[{"day":"Day 1","title":"Nairobi Cultural Tour","description":"Visit the National Museum, Bomas of Kenya, and Kazuri Beads factory."},{"day":"Day 2","title":"To Maasai Land","description":"Drive to Maasai community, welcome ceremony, and cultural exchange."},{"day":"Day 3","title":"Maasai Experience","description":"Full day with Maasai community. Learn about traditions, livestock, and daily life."},{"day":"Day 4","title":"Lake Nakuru Region","description":"Visit Lake Nakuru, explore local Kikuyu community."},{"day":"Day 5","title":"Samburu Cultural Visit","description":"Travel to Samburu region for unique cultural experiences."},{"day":"Day 6","title":"Return to Nairobi","description":"Morning activities and scenic drive back to Nairobi."}]'::jsonb, '["All ground transport","Accommodation","Meals as specified","Cultural activity fees","Professional guide","Community donations"]'::jsonb, '["Flights","Visa fees","Travel insurance","Personal shopping","Tips"]'::jsonb, 3),
('Mount Kenya Trekking Adventure', 'adventure', '5 Days / 4 Nights', 'From KSh 218,400', 218400, 'mount-kenya', 'Conquer Africa''s second-highest peak through stunning alpine landscapes.', 'Challenge yourself with a trek up Mount Kenya, Africa''s second-highest mountain. Experience dramatic changes in vegetation zones, stunning glacial landscapes, and the thrill of reaching Point Lenana at 4,985 meters.', '["Summit Point Lenana (4,985m)","Alpine lakes and glaciers","Diverse vegetation zones","Professional mountain guides","Stunning panoramic views"]'::jsonb, '[{"day":"Day 1","title":"Nanyuki to Old Moses Camp","description":"Drive to Sirimon Gate (2,650m), trek to Old Moses Camp (3,300m)."},{"day":"Day 2","title":"To Shiptons Camp","description":"Trek through moorland to Shiptons Camp (4,200m)."},{"day":"Day 3","title":"Acclimatization","description":"Short hikes for acclimatization around Shiptons Camp."},{"day":"Day 4","title":"Summit Day","description":"Pre-dawn start to Point Lenana. Descend to Mackinders Camp."},{"day":"Day 5","title":"Descent","description":"Trek down to the gate. Drive back to Nanyuki/Nairobi."}]'::jsonb, '["Mountain guides and porters","Camping equipment","All meals on mountain","Park fees","Transport to/from gate"]'::jsonb, '["Flights","Personal trekking gear","Travel insurance","Tips","Pre/post accommodation"]'::jsonb, 4),
('Amboseli & Tsavo Safari Combo', 'wildlife', '6 Days / 5 Nights', 'From KSh 245,700', 245700, 'safari-jeep', 'Two iconic parks in one trip — Amboseli''s elephants with Kilimanjaro views and Tsavo''s red elephants.', 'Combine two of Kenya''s most iconic national parks. See massive elephant herds against the backdrop of Mount Kilimanjaro in Amboseli, then explore the vast wilderness of Tsavo with its famous red elephants and diverse birdlife.', '["Kilimanjaro views from Amboseli","Large elephant herds","Tsavo red elephants","Mzima Springs","Diverse ecosystems"]'::jsonb, '[{"day":"Day 1","title":"Nairobi to Amboseli","description":"Morning departure, arrive Amboseli for afternoon game drive."},{"day":"Day 2","title":"Amboseli Full Day","description":"Full day game drives with Kilimanjaro backdrop."},{"day":"Day 3","title":"Amboseli to Tsavo West","description":"Morning game drive, transfer to Tsavo West. Afternoon drive."},{"day":"Day 4","title":"Tsavo West Exploration","description":"Visit Mzima Springs, Shetani Lava Flow. Game drives."},{"day":"Day 5","title":"Tsavo East","description":"Transfer to Tsavo East. Explore Lugard Falls and Galana River."},{"day":"Day 6","title":"Return to Nairobi","description":"Morning game drive, drive back to Nairobi."}]'::jsonb, '["Safari vehicle with guide","Full board accommodation","Park fees","Game drives","Bottled water"]'::jsonb, '["Flights","Visa","Travel insurance","Tips","Personal items"]'::jsonb, 5),
('Luxury Lodge Safari Experience', 'custom', '7 Days / 6 Nights', 'From KSh 455,000', 455000, 'safari-lodge', 'The ultimate luxury safari with premium lodges, private game drives, and exclusive experiences.', 'Indulge in Kenya''s finest safari experience. Stay at award-winning luxury lodges, enjoy private game drives, bush dinners under the stars, and spa treatments in the wilderness. This is safari at its most refined.', '["Luxury lodge accommodation","Private game drives","Bush dinner under stars","Spa in the wilderness","Hot air balloon safari","Champagne breakfast"]'::jsonb, '[{"day":"Day 1","title":"Arrival & Nairobi","description":"VIP airport meet and greet. Luxury hotel in Nairobi."},{"day":"Day 2","title":"Fly to Masai Mara","description":"Charter flight to Mara. Afternoon private game drive."},{"day":"Day 3","title":"Mara Luxury Experience","description":"Hot air balloon safari, champagne breakfast. Afternoon game drive."},{"day":"Day 4","title":"Bush Dinner","description":"Morning drive, spa afternoon, bush dinner under the stars."},{"day":"Day 5","title":"Fly to Amboseli","description":"Charter to Amboseli luxury lodge. Evening game drive."},{"day":"Day 6","title":"Amboseli Exclusive","description":"Private game drive, Kilimanjaro views, farewell dinner."},{"day":"Day 7","title":"Departure","description":"Charter back to Nairobi. VIP departure assistance."}]'::jsonb, '["Charter flights","Luxury lodge accommodation","All meals & drinks","Private guide & vehicle","Hot air balloon","Spa treatments","Park fees"]'::jsonb, '["International flights","Visa fees","Travel insurance","Tips","Personal shopping"]'::jsonb, 6);
